import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv2d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv2d_forward_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int in_height, int in_width,
    int out_height, int out_width,
    int kernel_h, int kernel_w,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    bool has_bias,
    int total_output_elements
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_output_elements) return;

    int n = idx / (out_channels * out_height * out_width);
    int remainder = idx % (out_channels * out_height * out_width);
    int oc = remainder / (out_height * out_width);
    remainder = remainder % (out_height * out_width);
    int oh = remainder / out_width;
    int ow = remainder % out_width;

    float sum = 0.0f;

    for (int ic = 0; ic < in_channels; ic++) {
        for (int kh = 0; kh < kernel_h; kh++) {
            for (int kw = 0; kw < kernel_w; kw++) {
                int ih = oh * stride_h + kh * dilation_h - padding_h;
                int iw = ow * stride_w + kw * dilation_w - padding_w;

                if (ih >= 0 && ih < in_height && iw >= 0 && iw < in_width) {
                    int input_idx = n * in_channels * in_height * in_width + ic * in_height * in_width + ih * in_width + iw;
                    int weight_idx = oc * in_channels * kernel_h * kernel_w + ic * kernel_h * kernel_w + kh * kernel_w + kw;
                    sum += __ldg(input + input_idx) * __ldg(weight + weight_idx);
                }
            }
        }
    }

    if (has_bias) {
        sum += __ldg(bias + oc);
    }

    output[idx] = sum;
}

torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int padding_h, int padding_w,
    int stride_h, int stride_w,
    int dilation_h, int dilation_w,
    bool has_bias
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto in_height = input.size(2);
    auto in_width = input.size(3);

    auto out_channels = weight.size(0);
    auto kernel_h = weight.size(2);
    auto kernel_w = weight.size(3);

    int out_height = (in_height + 2 * padding_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    int out_width = (in_width + 2 * padding_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    auto output = torch::zeros({batch_size, out_channels, out_height, out_width}, input.options());

    int total_output_elements = output.numel();
    const int threads_per_block = 256;
    int num_blocks = (total_output_elements + threads_per_block - 1) / threads_per_block;

    conv2d_forward_kernel<<<num_blocks, threads_per_block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_height, in_width,
        out_height, out_width,
        kernel_h, kernel_w,
        stride_h, stride_w,
        padding_h, padding_w,
        dilation_h, dilation_w,
        has_bias,
        total_output_elements
    );

    return output;
}
"""

conv2d_cpp_source = """
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int padding_h, int padding_w,
    int stride_h, int stride_w,
    int dilation_h, int dilation_w,
    bool has_bias
);
"""

conv2d_extension = load_inline(
    name="conv2d_extension",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_cuda_source,
    functions=["conv2d_forward_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = (stride, stride) if isinstance(stride, int) else stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        self.weight = nn.Parameter(torch.Tensor(out_channels, in_channels, kernel_size[0], kernel_size[1]))
        if self.has_bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.has_bias:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv2d_extension.conv2d_forward_cuda(
            x,
            self.weight,
            self.bias if self.has_bias else torch.empty(0),
            self.padding[0], self.padding[1],
            self.stride[0], self.stride[1],
            self.dilation[0], self.dilation[1],
            self.has_bias
        )
